Question: 有以下程序代码
#include<iostream>
using namespace std;
class integer{
public:
integer(int value=0):value(value){}
integer operator+(integer itg){
return value+=itg.value;
}
friend ostream&operator<<(ostream&os,integer&it){
return os<<it.value;
}
private:
int value;
};
int main()
{
integer i;
integer ii;
ii=2+i;
cout<<"i="<<i<<",";
cout<<"ii="<<ii<<endl;
return 0;
}
编译情况或运行时输出是____
A. i=0 ,ii=2
B. i=2 ,ii=2
C. i=0 ,ii=0
D. 编译错误

只输出一个字母。
Option A: i=0 ,ii=2
Option B: i=2 ,ii=2
Option C: i=0 ,ii=0
Option D: 编译错误
